// 本地嵌入兜底静态资源（防止 file:// 或离线环境下的图片加载异常）
window.DAFEIYU_CHIBI_B64 = "data:image/png;base64,";
window.DAFEIYU_LOGO_B64 = "data:image/png;base64,";

document.addEventListener("DOMContentLoaded", function() {
  document.querySelectorAll("img").forEach(function(img) {
    img.addEventListener("error", function() {
      if (img.src.indexOf("chibi") !== -1 && window.DAFEIYU_CHIBI_B64) {
        img.src = window.DAFEIYU_CHIBI_B64;
      } else if (img.src.indexOf("logo") !== -1 && window.DAFEIYU_LOGO_B64) {
        img.src = window.DAFEIYU_LOGO_B64;
      }
    });
  });
});
